<?php
declare(strict_types=1);require __DIR__.'/config.php';require __DIR__.'/functions.php';require_login();$user=current_user();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$title=trim((string)($_POST['title']??''));$description=trim((string)($_POST['description']??''));$tags=trim((string)($_POST['tags']??''));$category=(int)($_POST['category_id']??0);$visibility=in_array($_POST['visibility']??'unlisted',['public','unlisted','private'],true)?$_POST['visibility']:'unlisted';if($title===''||mb_strlen($title)>120)throw new RuntimeException('Judul wajib diisi dan maksimal 120 karakter.');if(!$category)throw new RuntimeException('Pilih kategori karya.');$check=$pdo->prepare('SELECT COUNT(*) FROM categories WHERE id=?');$check->execute([$category]);if(!(int)$check->fetchColumn())throw new RuntimeException('Kategori tidak valid.');$file=store_image($_FILES['template_image']??[],__DIR__.'/uploads');$moderation=$visibility==='public'?'pending':'approved';$pdo->prepare('INSERT INTO twibbons(slug,owner_id,category_id,visibility,title,description,tags,template_image,moderation_status) VALUES(?,?,?,?,?,?,?,?,?)')->execute([random_slug(),$user['id'],$category,$visibility,$title,$description,$tags,$file,$moderation]);flash('success',$visibility==='public'?'Karya dikirim untuk ditinjau admin.':'Karya berhasil dibuat.');redirect('dashboard');}catch(Throwable $e){$error=$e->getMessage();}}
$categories=$pdo->query('SELECT id,name FROM categories ORDER BY name')->fetchAll();
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Buat Karya — Semarakin</title><link rel="stylesheet" href="style.css"><link rel="stylesheet" href="teal.css"><link rel="stylesheet" href="auth.css"></head><body><header class="site-header"><div class="container nav"><a class="brand" href="./"><span class="brand-mark">S</span>Semarakin</a></div></header><main class="container create-work-page"><div class="page-head"><a class="eyebrow" href="dashboard">← Kembali ke dashboard</a><h1 class="page-title" style="margin-top:14px">Buat karya baru</h1><p class="subtitle">Lengkapi detail karya, tentukan akses, lalu unggah bingkai terbaikmu.</p></div><?php if($error):?><div class="alert alert-error"><?=e($error)?></div><?php endif?><div class="create-work-layout"><aside class="create-work-guide"><span class="category-symbol"><i></i></span><h2>Sebelum mengunggah</h2><ul><li>Gunakan PNG transparan untuk hasil terbaik.</li><li>Disarankan berukuran persegi dan resolusi tinggi.</li><li>Karya publik akan ditinjau oleh admin.</li></ul></aside><section class="panel"><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="field"><label for="title">Judul kampanye</label><input id="title" name="title" maxlength="120" required value="<?=e($_POST['title']??'')?>" placeholder="Contoh: Hari Lingkungan 2026"></div><div class="field"><label for="description">Deskripsi</label><textarea id="description" name="description" rows="4" maxlength="500" placeholder="Ceritakan tujuan kampanye ini"><?=e($_POST['description']??'')?></textarea></div><div class="field"><label for="category_id">Kategori</label><select id="category_id" name="category_id" required><option value="">Pilih kategori</option><?php foreach($categories as $cat):?><option value="<?=(int)$cat['id']?>" <?=((int)($_POST['category_id']??0)===(int)$cat['id'])?'selected':''?>><?=e($cat['name'])?></option><?php endforeach?></select></div><div class="field"><label for="tags">Tag pencarian</label><input id="tags" name="tags" maxlength="300" value="<?=e($_POST['tags']??'')?>" placeholder="sekolah, lingkungan, komunitas"><small class="field-help">Pisahkan setiap tag dengan koma.</small></div><div class="field"><label for="visibility">Siapa yang dapat mengakses?</label><select id="visibility" name="visibility"><option value="public">Publik — tampil di Jelajahi setelah ditinjau</option><option value="unlisted" selected>Via tautan — hanya orang yang memiliki URL</option><option value="private">Pribadi — hanya saya dan admin</option></select></div><div class="field"><label for="template_image">File bingkai</label><label class="work-upload" for="template_image"><span>↑</span><strong>Pilih PNG, JPG, atau WebP</strong><small>Maksimal 8 MB</small></label><input id="template_image" name="template_image" type="file" accept="image/png,image/jpeg,image/webp" required hidden></div><div class="create-form-actions"><a class="btn btn-secondary" href="dashboard">Batal</a><button class="btn btn-primary">Publikasikan karya</button></div></form></section></div></main><footer class="footer">Semarakin · Produk digital dari Apins Digital</footer><script>const input=document.querySelector('#template_image'),label=document.querySelector('.work-upload strong');input.addEventListener('change',()=>{if(input.files[0])label.textContent=input.files[0].name});</script></body></html>
